(3605142, 504580, 43400, '<td valign="top">great catch and timing</td>', 'great catch and timing', '2007-05-02 10:43:43.000000', NULL, 1),
(3605156, 506115, 67152, '<td valign="top">There is something very strange about this photo that I can''t quite put my finger on - the cropping is on the money and the image appears to be even across and up and down, but it still appears not centered for some reason - it must be the shadow of the railing or possibly your placement when taking the photo - it almost seems that you weren''t quite dead center when this photo was taken... I wish I could figure it out. <br/> <br/>I really like the perspective and contrast in this photo a lot..7</td>', 'There is something very strange about this photo that I can''t quite put my finger on - the cropping is on the money and the image appears to be even across and up and down, but it still appears not centered for some reason - it must be the shadow of the railing or possibly your placement when taking the photo - it almost seems that you weren''t quite dead center when this photo was taken... I wish I could figure it out.  I really like the perspective and contrast in this photo a lot..7', '2007-05-02 10:45:57.000000', NULL, 1),
(3605166, 506056, 67152, '<td valign="top">I like the crispness and colors on this image and the repeating patters is really nice - but I don''t really see symmetry - there is no reflection plane that I can see to superimpose the image on.  still it gets a 7</td>', 'I like the crispness and colors on this image and the repeating patters is really nice - but I don''t really see symmetry - there is no reflection plane that I can see to superimpose the image on.  still it gets a 7', '2007-05-02 10:47:42.000000', NULL, 1),
(3605170, 505883, 67152, '<td valign="top">would like this one a little crisper in focus - nice perspective though</td>', 'would like this one a little crisper in focus - nice perspective though', '2007-05-02 10:48:30.000000', NULL, 1),
(3605179, 504287, 67152, '<td valign="top">Beautiful house and nice image - but the perspective here really doesn''t shout out symmetry.  There are many symmetric elements in the building but the off centered placement far from away the house does not show us really clearly.  A close up of the arches and windows dead on would likely work a lot better.</td>', 'Beautiful house and nice image - but the perspective here really doesn''t shout out symmetry.  There are many symmetric elements in the building but the off centered placement far from away the house does not show us really clearly.  A close up of the arches and windows dead on would likely work a lot better.', '2007-05-02 10:50:48.000000', NULL, 1),
(3605273, 505779, 42181, '<td valign="top">Very symmetrical IMO shame you cropped off the right edge.</td>', 'Very symmetrical IMO shame you cropped off the right edge.', '2007-05-02 11:20:03.000000', NULL, 1),
