(3614417, 505083, 54446, '<td valign="top">My favorite in the challenge, so far.  This is spectacular.  Great job!  (10)</td>', 'My favorite in the challenge, so far.  This is spectacular.  Great job!  (10)', '2007-05-04 11:12:01.000000', NULL, 1),
(3614483, 505593, 66384, '<td valign="top">Needs straightening just a tad. And too bad about the jet trail. Pretty and imposing building.</td>', 'Needs straightening just a tad. And too bad about the jet trail. Pretty and imposing building.', '2007-05-04 11:31:59.000000', NULL, 1),
(3614491, 505844, 71958, '<td valign="top">this picture just doesn''t appeal to me, technically or from a symmetry perspective.  did I miss what you were going for?...</td>', 'this picture just doesn''t appeal to me, technically or from a symmetry perspective.  did I miss what you were going for?...', '2007-05-04 11:34:35.000000', NULL, 1),
(3614492, 506085, 66384, '<td valign="top">Good sports shot, but I don''t see the symmetry in it.</td>', 'Good sports shot, but I don''t see the symmetry in it.', '2007-05-04 11:34:52.000000', NULL, 1),
(3614498, 503480, 74953, '<td valign="top">The lens flare in the lower right takes away from the photo.  You may have been able to crop that out, and still retained most of the photo.</td>', 'The lens flare in the lower right takes away from the photo.  You may have been able to crop that out, and still retained most of the photo.', '2007-05-04 11:36:20.000000', NULL, 1),
(3614499, 505503, 71958, '<td valign="top">i really lik ethe texture, but from a symetry perspective i wish you could see as much of the boat above the water as you do in the water.</td>', 'i really lik ethe texture, but from a symetry perspective i wish you could see as much of the boat above the water as you do in the water.', '2007-05-04 11:36:26.000000', NULL, 1),
(3614500, 506092, 66384, '<td valign="top">Odd how it looks twisted as though it is about to tall down. Beautiful reflection.</td>', 'Odd how it looks twisted as though it is about to tall down. Beautiful reflection.', '2007-05-04 11:36:46.000000', NULL, 1),
(3614506, 505868, 71958, '<td valign="top">definitely symmetrical, nice technical, but the subject is a little boring.</td>', 'definitely symmetrical, nice technical, but the subject is a little boring.', '2007-05-04 11:37:49.000000', NULL, 1),
(3614512, 505083, 71958, '<td valign="top">there is too much going on here.  perhaps a solid background?...</td>', 'there is too much going on here.  perhaps a solid background?...', '2007-05-04 11:38:31.000000', NULL, 1),
(3614516, 506050, 66384, '<td valign="top">So beautiful and sad. The moon is an extra bonus here. Great fit for the challenge. 9</td>', 'So beautiful and sad. The moon is an extra bonus here. Great fit for the challenge. 9', '2007-05-04 11:39:14.000000', NULL, 1),
(3614518, 506118, 71958, '<td valign="top">nice capture, but i think having the dock centered and composing or cropping so that the all the mast as fully visible in the water would both improve the symmetry</td>', 'nice capture, but i think having the dock centered and composing or cropping so that the all the mast as fully visible in the water would both improve the symmetry', '2007-05-04 11:40:23.000000', NULL, 1),
(3614526, 505330, 66384, '<td valign="top">Beautiful image, but not very symmetrical. I love the line of the river curving off to the right, and the light, contrast, and color are especially nice.</td>', 'Beautiful image, but not very symmetrical. I love the line of the river curving off to the right, and the light, contrast, and color are especially nice.', '2007-05-04 11:42:13.000000', NULL, 1),
(3614537, 504218, 66384, '<td valign="top">I don''t care for the intensified colors. Also the image is not very symmetrical.</td>', 'I don''t care for the intensified colors. Also the image is not very symmetrical.', '2007-05-04 11:45:18.000000', NULL, 1),
(3614558, 506056, 74953, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2007-05-04 11:51:42.000000', NULL, 1),
(3614575, 505844, 66384, '<td valign="top">Looks more like bubbles than symmetry.</td>', 'Looks more like bubbles than symmetry.', '2007-05-04 11:55:21.000000', NULL, 1),
(3614588, 506142, 66384, '<td valign="top">Nice gradation in color and pattern.</td>', 'Nice gradation in color and pattern.', '2007-05-04 11:59:08.000000', NULL, 1),
(3614601, 506098, 66384, '<td valign="top">Sorry, I don''t see any symmetry in this image at all -- completely asymmetrical.</td>', 'Sorry, I don''t see any symmetry in this image at all -- completely asymmetrical.', '2007-05-04 12:01:56.000000', NULL, 1),
(3614613, 503387, 66384, '<td valign="top">Pretty good trick, getting the drops to match so closely.</td>', 'Pretty good trick, getting the drops to match so closely.', '2007-05-04 12:04:17.000000', NULL, 1),
(3614619, 505587, 66384, '<td valign="top">Very striking image! I like the use of just two colors, and you really nailed the symmetry. 10</td>', 'Very striking image! I like the use of just two colors, and you really nailed the symmetry. 10', '2007-05-04 12:06:20.000000', NULL, 1),
(3614630, 505895, 66384, '<td valign="top">Nope, don''t see any symmetry here.</td>', 'Nope, don''t see any symmetry here.', '2007-05-04 12:09:20.000000', NULL, 1),
(3614637, 505869, 71958, '<td valign="top">very nice capture, i really lik ethe perspective!</td>', 'very nice capture, i really lik ethe perspective!', '2007-05-04 12:11:39.000000', NULL, 1),
(3614647, 506054, 66384, '<td valign="top">There''s a lot of symmetry in the building, but not in the image. I think it would have been more effective for the challenge if you had balanced the two sides. BUT, challenge aside, this is a very nice shot. I like the light, patterns, and perspective.</td>', 'There''s a lot of symmetry in the building, but not in the image. I think it would have been more effective for the challenge if you had balanced the two sides. BUT, challenge aside, this is a very nice shot. I like the light, patterns, and perspective.', '2007-05-04 12:13:10.000000', NULL, 1),
