(3631525, 504732, 64994, '<td valign="top">COOL! way to go!! very nice shot! Love the PP in this one!! very basic, and very very good!!!</td>', 'COOL! way to go!! very nice shot! Love the PP in this one!! very basic, and very very good!!!', '2007-05-09 02:50:50.000000', NULL, 0),
(3631527, 504628, 59905, '<td valign="top">Woohoo a 5.745 for my first entry! :-D<br/> <br/>hahn23, it surely wasn''t my intention to influence voting, which I added immediately in the thread when I found out it was felt like that (and ask for closure of the thread, and stopped responding to prevent bumping..). <br/>I''m sorry it went that way and will definitely think twice about immediate posting when I feel something about a challenge. If I will and still do after the voting has closed, then I might speak out, but not earlier anymore no!<br/>I do find it quite disappointing that you think about generalizing my behavior to everyone in this country, that somehow seems totally inappropriate, although I cannot see whether you asked it to see it in proportion (if everyone does it here, it''s not strange I do too). Honesty is the main way to go here, and that''s the light in which I posted. (I was truly thinking that many lake reflections and flower macros stretch the definition; I''ll have to adjust my mindset so it fits with the DPC majority I suppose).<br/>Btw, congrats on your 7th place! It''ll take a while for me to meet you there ;-)</td>', 'Woohoo a 5.745 for my first entry! :-D hahn23, it surely wasn''t my intention to influence voting, which I added immediately in the thread when I found out it was felt like that (and ask for closure of the thread, and stopped responding to prevent bumping..). I''m sorry it went that way and will definitely think twice about immediate posting when I feel something about a challenge. If I will and still do after the voting has closed, then I might speak out, but not earlier anymore no!I do find it quite disappointing that you think about generalizing my behavior to everyone in this country, that somehow seems totally inappropriate, although I cannot see whether you asked it to see it in proportion (if everyone does it here, it''s not strange I do too). Honesty is the main way to go here, and that''s the light in which I posted. (I was truly thinking that many lake reflections and flower macros stretch the definition; I''ll have to adjust my mindset so it fits with the DPC majority I suppose).Btw, congrats on your 7th place! It''ll take a while for me to meet you there ;-)', '2007-05-09 02:52:10.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3631536, 505754, 73601, '<td valign="top">Grats on your new Pb!</td>', 'Grats on your new Pb!', '2007-05-09 02:56:01.000000', NULL, 0),
(3631553, 505869, 43073, '<td valign="top">I had to come back and see this. I''m so pleased this was your shot, Deb. I gave you a ten on this, and am really surprised and somewhat mystified that it didn''t do better. I can''t explain it. It was so perfectly seen, captured and presented, and such a unique take on the challenge. Oh, <i><b>that''s</b></i> it! Unique. Silly person, thinking a unique and thoughtful take on a challenge was a good idea (just joking). Anyway, I love it.</td>', 'I had to come back and see this. I''m so pleased this was your shot, Deb. I gave you a ten on this, and am really surprised and somewhat mystified that it didn''t do better. I can''t explain it. It was so perfectly seen, captured and presented, and such a unique take on the challenge. Oh, that''s it! Unique. Silly person, thinking a unique and thoughtful take on a challenge was a good idea (just joking). Anyway, I love it.', '2007-05-09 03:07:51.000000', NULL, 0),
(3631567, 505237, 59905, '<td valign="top">Wow, this was one my favorites during the challenge (mainly due to the fact that the reflection here adds to the picture, as it looks as if the chain goes all the way around). I''d expected this one to do much better! Keep up the good work!</td>', 'Wow, this was one my favorites during the challenge (mainly due to the fact that the reflection here adds to the picture, as it looks as if the chain goes all the way around). I''d expected this one to do much better! Keep up the good work!', '2007-05-09 03:17:17.000000', NULL, 0),
(3631568, 504544, 43073, '<td valign="top">Congratulations, Sara, looks like you were right to be so upbeat throughout the challenge (on the scores thread; I was really waiting to see which shot was yours, there were so many good ones in this challenge). Great subject, wonderfully shot, and perfectly presented. Definitely deserving of your blue!</td>', 'Congratulations, Sara, looks like you were right to be so upbeat throughout the challenge (on the scores thread; I was really waiting to see which shot was yours, there were so many good ones in this challenge). Great subject, wonderfully shot, and perfectly presented. Definitely deserving of your blue!', '2007-05-09 03:17:20.000000', NULL, 0),
(3631585, 505754, 52549, '<td valign="top">Congrats on your new Pb from me too, Monique. I love the clear lines, it''s a super image.</td>', 'Congrats on your new Pb from me too, Monique. I love the clear lines, it''s a super image.', '2007-05-09 03:28:30.000000', NULL, 0),
(3631589, 503752, 59335, '<td valign="top">So close to a metal!  Next time.</td>', 'So close to a metal!  Next time.', '2007-05-09 03:31:09.000000', NULL, 0),
(3631607, 505977, 30982, '<td valign="top">Nice work, as usual.  For some reason, it has a lovely light and airy "good day" kinda feel to it, despite the heavy chains.  Or maybe because of - who knows?  But I like it!</td>', 'Nice work, as usual.  For some reason, it has a lovely light and airy "good day" kinda feel to it, despite the heavy chains.  Or maybe because of - who knows?  But I like it!', '2007-05-09 03:46:16.000000', NULL, 0),
(3631621, 504544, 38509, '<td valign="top">go MAD SHUTTERS ! congratz !!!!</td>', 'go MAD SHUTTERS ! congratz !!!!', '2007-05-09 03:50:58.000000', NULL, 0),
(3631638, 505846, 49109, '<td valign="top">Congrats, Irene, brillant idea well executed!</td>', 'Congrats, Irene, brillant idea well executed!', '2007-05-09 03:58:20.000000', NULL, 0),
(3631676, 506121, 60862, '<td valign="top">Congrats, Jayson!  That''s a cool shot and a great new personal best!</td>', 'Congrats, Jayson!  That''s a cool shot and a great new personal best!', '2007-05-09 04:27:51.000000', NULL, 0),
(3631682, 505859, 65713, '<td valign="top">Thanks for the comments during voting, sorry I couldn''t respond earlier. I understand that the image isn''t perfectly symmetrical but kinda liked the way the trigrams(red line characters) inverted the symmetry as in the yin yang symbol each one represents an aspect of. Not very clear though and there are several other things that I fully understand receiving a lower vote for. <br/>   Anyway I beat my average and am therefore pleased with the result,........ 5.1!!!!!</td>', 'Thanks for the comments during voting, sorry I couldn''t respond earlier. I understand that the image isn''t perfectly symmetrical but kinda liked the way the trigrams(red line characters) inverted the symmetry as in the yin yang symbol each one represents an aspect of. Not very clear though and there are several other things that I fully understand receiving a lower vote for.    Anyway I beat my average and am therefore pleased with the result,........ 5.1!!!!!', '2007-05-09 04:31:00.000000', NULL, 0),
(3631683, 504797, 60862, '<td valign="top">Congrats, Kashi!  You''re on a roll with these 6+ scores. :)</td>', 'Congrats, Kashi!  You''re on a roll with these 6+ scores. :)', '2007-05-09 04:32:01.000000', NULL, 0),
(3631686, 503752, 52549, '<td valign="top">Very original and fantastic symmetry. Congrats on 4th place, Jason.</td>', 'Very original and fantastic symmetry. Congrats on 4th place, Jason.', '2007-05-09 04:37:56.000000', NULL, 0),
(3631692, 505846, 56167, '<td valign="top">congratulations Irene, a well deserved ribbon, knew this photo would be up in the top three.</td>', 'congratulations Irene, a well deserved ribbon, knew this photo would be up in the top three.', '2007-05-09 04:41:52.000000', NULL, 0),
(3631696, 505695, 65713, '<td valign="top">Really nice shot! DOF and contrast just perfect!</td>', 'Really nice shot! DOF and contrast just perfect!', '2007-05-09 04:46:57.000000', NULL, 0),
(3631787, 505273, 43073, '<td valign="top">I promised to come and comment on your image (in the scores thread), so here I am :) I am in "critique mode," so please don''t take anything I write as being overly critical; they are just my observations and opinion, and I am being intentionally critical (much more so than I might normally be) so that it is hopefully helpful!<br/> <br/>Okay, initially, the focus on this is very, very soft, and much of the image actually looks out of focus. This is possibly the biggest issue voters had with the shot. DPC voters like sharp, crisp focus. If you look at the winners in any challenge, they are all sharp without being too sharp; it''s one of the hallmarks of a winning shot here. You would probably have needed to use a higher aperture to bring more of the shot into focus and avoid the overall soft appearance you have here. There should be a way to do that with your camera (it might require you shooting in landscape mode or something similar, or you might be able to manually choose the aperture).<br/> <br/>It also appears this is a "setup" shot, that is, something you''ve specifically put together for the challenge and photographed. Because there are so many excellent photographers on DPC with advanced photographic studios and lighting, setup shots generally need to be near perfect technically. They need to be very well composed, focused, and well lit. I tend not to do setup shots because they are so competitive. Here, the focus issues come up again, and while the mirrors are present, the composition/crop of the shot minimizes them to a certain degree. The colors, while bright, are not really vibrant. Some work in processing to add saturation or play with curves/contrast might give the image more impact.<br/> <br/>I hope these two points help you see some of what I saw in your image (and maybe what some other voters might have seen). You have a good eye for what is visually interesting, and with some more attention to how you shoot and processing for impact after, your scores will steadily improve here. Good luck!</td>', 'I promised to come and comment on your image (in the scores thread), so here I am :) I am in "critique mode," so please don''t take anything I write as being overly critical; they are just my observations and opinion, and I am being intentionally critical (much more so than I might normally be) so that it is hopefully helpful! Okay, initially, the focus on this is very, very soft, and much of the image actually looks out of focus. This is possibly the biggest issue voters had with the shot. DPC voters like sharp, crisp focus. If you look at the winners in any challenge, they are all sharp without being too sharp; it''s one of the hallmarks of a winning shot here. You would probably have needed to use a higher aperture to bring more of the shot into focus and avoid the overall soft appearance you have here. There should be a way to do that with your camera (it might require you shooting in landscape mode or something similar, or you might be able to manually choose the aperture). It also appears this is a "setup" shot, that is, something you''ve specifically put together for the challenge and photographed. Because there are so many excellent photographers on DPC with advanced photographic studios and lighting, setup shots generally need to be near perfect technically. They need to be very well composed, focused, and well lit. I tend not to do setup shots because they are so competitive. Here, the focus issues come up again, and while the mirrors are present, the composition/crop of the shot minimizes them to a certain degree. The colors, while bright, are not really vibrant. Some work in processing to add saturation or play with curves/contrast might give the image more impact. I hope these two points help you see some of what I saw in your image (and maybe what some other voters might have seen). You have a good eye for what is visually interesting, and with some more attention to how you shoot and processing for impact after, your scores will steadily improve here. Good luck!', '2007-05-09 05:51:06.000000', NULL, 0),
(3631811, 505521, 68467, '<td valign="top">Congrats on 25th place</td>', 'Congrats on 25th place', '2007-05-09 06:13:46.000000', NULL, 0),
(3631848, 505776, 67152, '<td valign="top">Really nice image Catherine - love the depths of the green tones in the leaves, the dew to add needed contrast, and the placement at an angle across the field of view.  I think this last observation may have hurt you a little with the viewers as people wanted to see a ''symmetrical'' image more than symmetrical objects.  I gave it a 7 during the challenge.</td>', 'Really nice image Catherine - love the depths of the green tones in the leaves, the dew to add needed contrast, and the placement at an angle across the field of view.  I think this last observation may have hurt you a little with the viewers as people wanted to see a ''symmetrical'' image more than symmetrical objects.  I gave it a 7 during the challenge.', '2007-05-09 06:59:23.000000', NULL, 0),
(3631853, 505381, 67152, '<td valign="top">I thought this was an awesome perspective and gave it a 9 during the challenge.  Great lighting, colors, and repeating lines.  I can''t understand why anyone would give this a 1 or 2, but maybe the presence of the person in the far right made it not symmetrical to them - I don''t get it!!!   Great job.</td>', 'I thought this was an awesome perspective and gave it a 9 during the challenge.  Great lighting, colors, and repeating lines.  I can''t understand why anyone would give this a 1 or 2, but maybe the presence of the person in the far right made it not symmetrical to them - I don''t get it!!!   Great job.', '2007-05-09 07:08:23.000000', NULL, 0),
